{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The Glass Diver arrives at the ruined city gates.",
      "visual_description": "A massive iron gate hangs askew, vines crawling over old royal banners. The Glass Diver stands before it, their diving helmet reflecting the shattered city skyline.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 2,
      "caption": "Mara the Cartographer unfolds a map and points ahead.",
      "visual_description": "Mara unrolls a stained parchment map, her brass compass glinting. She gestures toward a crooked tower while the Glass Diver peers over her shoulder.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 3,
      "caption": "The Oracle Lamp warns of a cursed tower ahead.",
      "visual_description": "The Oracle Lamp flickers, its single flame-eye glowing bright. It speaks as the group stands before a spiraling tower covered in frost and runes.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 4,
      "caption": "The Tin Fox scouts ahead through rubble.",
      "visual_description": "The Tin Fox winds its key-tail and scurries over broken stone, its blue glass eyes scanning beneath a fallen archway.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "The group encounters a sleeping tax collector at a checkpoint.",
      "visual_description": "The Sleeping Tax Collector snores on a pile of stamped papers, a ledger book under his head. Stamped papers flutter from his sleeves in the breeze.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 6,
      "caption": "Mara traces a route around the sleeping official.",
      "visual_description": "Mara kneels, inking a new path on her map while the Glass Diver watches the tower shadows lengthen. The Oracle Lamp casts a weary glow.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 7,
      "caption": "The Tin Fox finds a hidden passage behind a magic door.",
      "visual_description": "The Tin Fox presses its nose to a shimmering door carved with shifting symbols. Its key-tail ticks as the door hums.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 8,
      "caption": "The Glass Diver swims through the magic door's surface.",
      "visual_description": "The Glass Diver steps into the door's rippling surface, their coat reflecting the city lights as they pass through like a swimmer into deep water.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 9,
      "caption": "Mara and the Oracle Lamp follow through the door.",
      "visual_description": "Mara steps through the now-calm door, holding the Oracle Lamp high. The lamp's eye scans the dark corridor beyond.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 10,
      "caption": "The Tin Fox reports a patrol of armored figures nearby.",
      "visual_description": "The Tin Fox returns, its metal ears twitching. Through a crack in the wall, armored patrols march in the plaza outside.",
      "characters": ["tin_fox", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 11,
      "caption": "The Oracle Lamp warns of danger from the patrols.",
      "visual_description": "The Oracle Lamp's flame dims as it whispers a warning. The group presses against the wall, shadows of patrols passing.",
      "characters": ["oracle_lamp", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 12,
      "caption": "The Sleeping Tax Collector wakes and stumbles into view.",
      "visual_description": "The Sleeping Tax Collector shuffles into the plaza, rubbing his eyes, stamping papers still stuck to his sleeves. The patrols ignore him.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 13,
      "caption": "The group uses the distraction to cross a courtyard.",
      "visual_description": "While the patrols watch the tax collector, the Glass Diver, Mara, the Oracle Lamp, and the Tin Fox dash across the cracked courtyard under tattered banners.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 14,
      "caption": "They reach a room filled with old royal banners.",
      "visual_description": "Dusty banners hang from a high ceiling, embroidered with faded crests. Moonlight streams through a broken window onto the cloth.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 15,
      "caption": "The Glass Diver sees a reflection of the escape bridge in a mirror.",
      "visual_description": "A cracked mirror on the wall shows the bridge leading out of the city. The Glass Diver touches its surface, feeling the way.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 16,
      "caption": "The Tin Fox triggers a mechanism that opens a secret exit.",
      "visual_description": "The Tin Fox presses a hidden switch behind a banner. Stone grinds as a door slides open, revealing a path toward the bridge.",
      "characters": ["tin_fox", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 17,
      "caption": "The group races across the final bridge.",
      "visual_description": "The bridge spans a dark chasm, old royal banners hanging from its rails. The Glass Diver leads, Mara and the Oracle Lamp close behind, the Tin Fox scouting ahead.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "They escape beyond the bridge as the city crumbles behind them.",
      "visual_description": "The group reaches the far side. Behind them, the ruined city collapses into dust. The Glass Diver removes their helmet, breathing free air.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    }
  ]
}

